-- ===== U11 vocab 覆盖灌库(volume='9',48词)。分步跑。=====

SELECT 'U11 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U11';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U11';
SELECT 'U11 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U11';  -- 应0


SELECT 'U11 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U11';  -- 应48
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U11' GROUP BY word HAVING count(*)>1;  -- 查重应0行